-- Plan « CLM court et triathlon S en aéro » (8 semaines) : 30 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('e_cont', 'fr', 'Endurance TT {n}×{d}', 'Objectif physiologique : Développer l''endurance fondamentale et la base aérobie. Objectif aéro : Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs.', 'Endurance fondamentale en position TT : intensité facile pour que toute l''attention aille à la tenue (tête basse, épaules relâchées, appui stable). Les blocs s''allongent d''une semaine à l''autre.'),
('e_cont', 'en', 'TT endurance {n}×{d}', 'Physiological goal: Build base endurance and your aerobic base. Aero goal: Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks.', 'Base endurance in the TT position: easy intensity so all your attention goes to holding it (head low, shoulders relaxed, stable support). The blocks get longer every week.'),
('e_cont', 'es', 'Resistencia TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la resistencia básica y la base aeróbica. Objetivo aero: Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques.', 'Resistencia básica en posición TT: intensidad suave para que toda la atención vaya a mantenerla (cabeza baja, hombros relajados, apoyo estable). Los bloques se alargan cada semana.'),
('e_cont', 'it', 'Resistenza TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la resistenza di base e la base aerobica. Obiettivo aero: Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi.', 'Resistenza di base in posizione TT: intensità facile perché l''attenzione vada tutta alla tenuta (testa bassa, spalle rilassate, appoggio stabile). I blocchi si allungano ogni settimana.'),
('e_cont', 'de', 'TT-Ausdauer {n}×{d}', 'Physiologisches Ziel: Grundlagenausdauer und aerobe Basis entwickeln. Aero-Ziel: Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten.', 'Grundlagenausdauer in TT-Position: leichte Intensität, damit die ganze Aufmerksamkeit dem Halten gilt (Kopf tief, Schultern locker, stabile Auflage). Die Blöcke werden jede Woche länger.'),
('e_cont', 'nl', 'TT-duur {n}×{d}', 'Fysiologisch doel: Basisduur en je aerobe basis ontwikkelen. Aerodoel: De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken.', 'Basisduur in TT-houding: lichte intensiteit zodat al je aandacht naar het vasthouden gaat (hoofd laag, schouders ontspannen, stabiele steun). De blokken worden elke week langer.'),
('e_cont', 'pt', 'Resistência TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a resistência de base e a base aeróbia. Objetivo aero: Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos.', 'Resistência de base na posição TT: intensidade leve para que toda a atenção vá para mantê-la (cabeça baixa, ombros relaxados, apoio estável). Os blocos ficam mais longos a cada semana.'),
('e_cont', 'ja', 'TT持久 {n}×{d}', '生理学的目標：基礎持久力と有酸素ベースを伸ばす。 エアロ目標：持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。', 'TTポジションでの基礎持久力：強度は楽にして保つことに集中（頭を低く、肩の力を抜き、安定した支え）。ブロックは週ごとに長くなります。'),
('e_cont', 'tr', 'TT dayanıklılık {n}×{d}', 'Fizyolojik hedef: Temel dayanıklılığı ve aerobik temeli geliştirmek. Aero hedefi: Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma.', 'TT pozisyonunda temel dayanıklılık: tüm dikkatin pozisyonu korumakta olsun diye kolay yoğunluk (baş aşağıda, omuzlar gevşek, sabit destek). Bloklar her hafta uzar.'),
('e_long', 'fr', 'Fond TT {m}''', 'Objectif physiologique : Développer la base aérobie et la résistance à la fatigue sur la durée. Objectif aéro : Accumuler le plus long temps en TT de la semaine à 70-72 % FTP.', 'Sortie longue : de longs blocs en TT entrecoupés de courtes pauses redressées. Cherche une position que tu peux tenir, pas la plus basse.'),
('e_long', 'en', 'Long TT ride {m}''', 'Physiological goal: Build your aerobic base and fatigue resistance over time. Aero goal: Build up the longest TT time of the week at 70-72% FTP.', 'Long ride: long TT blocks broken up by short upright breaks. Find a position you can hold, not the lowest one.'),
('e_long', 'es', 'Fondo TT {m}''', 'Objetivo fisiológico: Desarrollar la base aeróbica y la resistencia a la fatiga en la duración. Objetivo aero: Acumular el mayor tiempo en TT de la semana al 70-72 % FTP.', 'Salida larga: bloques largos en TT con pausas cortas erguido. Busca una posición que puedas mantener, no la más baja.'),
('e_long', 'it', 'Fondo TT {m}''', 'Obiettivo fisiologico: Sviluppare la base aerobica e la resistenza alla fatica sulla durata. Obiettivo aero: Accumulare il tempo in TT più lungo della settimana al 70-72 % FTP.', 'Uscita lunga: lunghi blocchi in TT con brevi pause eretto. Cerca una posizione che puoi tenere, non la più bassa.'),
('e_long', 'de', 'Lange TT-Fahrt {m}''', 'Physiologisches Ziel: Aerobe Basis und Ermüdungsresistenz über die Dauer entwickeln. Aero-Ziel: Die längste TT-Zeit der Woche bei 70-72 % FTP sammeln.', 'Lange Fahrt: lange TT-Blöcke mit kurzen aufrechten Pausen. Such eine Position, die du halten kannst, nicht die tiefste.'),
('e_long', 'nl', 'Lange TT-rit {m}''', 'Fysiologisch doel: Je aerobe basis en weerstand tegen vermoeidheid over de duur ontwikkelen. Aerodoel: De langste TT-tijd van de week opbouwen op 70-72 % FTP.', 'Lange rit: lange TT-blokken met korte pauzes rechtop. Zoek een houding die je kunt volhouden, niet de laagste.'),
('e_long', 'pt', 'Fundo TT {m}''', 'Objetivo fisiológico: Desenvolver a base aeróbia e a resistência à fadiga na duração. Objetivo aero: Acumular o maior tempo em TT da semana a 70-72 % FTP.', 'Treino longo: blocos longos em TT com pausas curtas ereto. Procure uma posição que consiga manter, não a mais baixa.'),
('e_long', 'ja', 'ロングTT {m}''', '生理学的目標：有酸素ベースと長時間の疲労耐性を伸ばす。 エアロ目標：70〜72 % FTPで週で最も長いTT時間を積み上げる。', 'ロングライド：短いアップライト休憩を挟んだ長いTTブロック。一番低い姿勢ではなく、維持できる姿勢を探して。'),
('e_long', 'tr', 'Uzun TT sürüş {m}''', 'Fizyolojik hedef: Aerobik temeli ve uzun sürede yorgunluğa direnci geliştirmek. Aero hedefi: %70-72 FTP''de haftanın en uzun TT süresini biriktir.', 'Uzun sürüş: kısa dik molalarla bölünmüş uzun TT blokları. En alçak değil, koruyabileceğin bir pozisyon bul.'),
('r_clm', 'fr', 'Allure CLM TT {n}×{d}', 'Objectif physiologique : Habituer l''organisme à l''intensité du CLM court (au-dessus du seuil). Objectif aéro : Tenir la position TT à l''allure du CLM (100-105 % FTP) du premier au dernier coup de pédale.', 'Simulation de CLM court (10 à 20 km) : l''effort et la position de la course, sans relâcher la tête ni les épaules quand la douleur monte. Récupère redressé entre les blocs.'),
('r_clm', 'en', 'TT race pace {n}×{d}', 'Physiological goal: Get used to short-TT intensity (above threshold). Aero goal: Hold the TT position at race pace (100-105% FTP) from the first to the last pedal stroke.', 'Short TT simulation (10 to 20 km): race effort and race position, without letting your head or shoulders go when it starts to hurt. Recover upright between blocks.'),
('r_clm', 'es', 'Ritmo CRI TT {n}×{d}', 'Objetivo fisiológico: Acostumbrar el organismo a la intensidad de la CRI corta (por encima del umbral). Objetivo aero: Mantener la posición TT a ritmo de CRI (100-105 % FTP) de la primera a la última pedalada.', 'Simulación de CRI corta (10 a 20 km): el esfuerzo y la posición de carrera, sin soltar cabeza ni hombros cuando sube el dolor. Recupera erguido entre bloques.'),
('r_clm', 'it', 'Ritmo crono TT {n}×{d}', 'Obiettivo fisiologico: Abituare l''organismo all''intensità della crono corta (sopra soglia). Obiettivo aero: Tenere la posizione TT al ritmo della crono (100-105 % FTP) dalla prima all''ultima pedalata.', 'Simulazione di crono corta (10-20 km): lo sforzo e la posizione di gara, senza mollare testa e spalle quando sale il dolore. Recupera eretto tra i blocchi.'),
('r_clm', 'de', 'Zeitfahrtempo TT {n}×{d}', 'Physiologisches Ziel: Den Körper an die Intensität eines kurzen Zeitfahrens gewöhnen (über der Schwelle). Aero-Ziel: Die TT-Position im Wettkampftempo (100-105 % FTP) vom ersten bis zum letzten Tritt halten.', 'Simulation eines kurzen Zeitfahrens (10 bis 20 km): Rennbelastung und Rennposition, ohne Kopf und Schultern loszulassen, wenn es wehtut. Zwischen den Blöcken aufrecht erholen.'),
('r_clm', 'nl', 'Tijdrittempo TT {n}×{d}', 'Fysiologisch doel: Je lichaam laten wennen aan de intensiteit van een korte tijdrit (boven drempel). Aerodoel: De TT-houding op wedstrijdtempo (100-105 % FTP) vasthouden van de eerste tot de laatste pedaalslag.', 'Simulatie van een korte tijdrit (10 tot 20 km): wedstrijdinspanning en wedstrijdhouding, zonder hoofd en schouders los te laten als het pijn gaat doen. Herstel rechtop tussen de blokken.'),
('r_clm', 'pt', 'Ritmo contrarrelógio TT {n}×{d}', 'Objetivo fisiológico: Habituar o organismo à intensidade do contrarrelógio curto (acima do limiar). Objetivo aero: Manter a posição TT no ritmo do contrarrelógio (100-105 % FTP) da primeira à última pedalada.', 'Simulação de contrarrelógio curto (10 a 20 km): o esforço e a posição de prova, sem soltar cabeça e ombros quando a dor aumenta. Recupere ereto entre os blocos.'),
('r_clm', 'ja', 'TTレースペース {n}×{d}', '生理学的目標：短いTTの強度（閾値以上）に体を慣らす。 エアロ目標：最初から最後のペダリングまで、TTレースペース（100〜105 % FTP）でポジションを保つ。', '短いTT（10〜20 km）のシミュレーション：苦しくなっても頭と肩を崩さず、レースの強度とポジションで。ブロックの間は起き上がって回復。'),
('r_clm', 'tr', 'Zamana karşı temposu TT {n}×{d}', 'Fizyolojik hedef: Vücudu kısa zamana karşı yoğunluğuna alıştırmak (eşiğin üzerinde). Aero hedefi: İlk pedaldan son pedala kadar yarış temposunda (%100-105 FTP) TT pozisyonunu koru.', 'Kısa zamana karşı simülasyonu (10-20 km): acı arttığında başı ve omuzları bırakmadan yarış eforu ve yarış pozisyonu. Bloklar arasında dik toparlan.'),
('t_cp', 'fr', 'Puissance critique TT {n}×{d}', 'Objectif physiologique : Faire monter la puissance critique. Objectif aéro : Tenir la position TT à 108-115 % FTP sur des efforts de 3 à 4 minutes.', 'Efforts de 3 à 4 minutes au-dessus du seuil, en TT : l''allure d''un prologue ou d''un CLM court. Récupération égale à l''effort, redressé.'),
('t_cp', 'en', 'TT critical power {n}×{d}', 'Physiological goal: Raise your critical power. Aero goal: Hold the TT position at 108-115% FTP over 3 to 4 minute efforts.', '3 to 4 minute efforts above threshold, in TT: the pace of a prologue or a short TT. Recovery as long as the effort, upright.'),
('t_cp', 'es', 'Potencia crítica TT {n}×{d}', 'Objetivo fisiológico: Subir la potencia crítica. Objetivo aero: Mantener la posición TT al 108-115 % FTP en esfuerzos de 3 a 4 minutos.', 'Esfuerzos de 3 a 4 minutos por encima del umbral, en TT: el ritmo de un prólogo o de una CRI corta. Recuperación igual al esfuerzo, erguido.'),
('t_cp', 'it', 'Potenza critica TT {n}×{d}', 'Obiettivo fisiologico: Alzare la potenza critica. Obiettivo aero: Tenere la posizione TT al 108-115 % FTP su sforzi da 3 a 4 minuti.', 'Sforzi da 3 a 4 minuti sopra soglia, in TT: il ritmo di un prologo o di una crono corta. Recupero pari allo sforzo, eretto.'),
('t_cp', 'de', 'Kritische Leistung TT {n}×{d}', 'Physiologisches Ziel: Die kritische Leistung steigern. Aero-Ziel: Die TT-Position bei 108-115 % FTP über 3 bis 4 Minuten halten.', '3- bis 4-minütige Belastungen über der Schwelle, in TT: das Tempo eines Prologs oder kurzen Zeitfahrens. Erholung so lang wie die Belastung, aufrecht.'),
('t_cp', 'nl', 'Kritisch vermogen TT {n}×{d}', 'Fysiologisch doel: Je kritisch vermogen verhogen. Aerodoel: De TT-houding vasthouden op 108-115 % FTP bij inspanningen van 3 tot 4 minuten.', 'Inspanningen van 3 tot 4 minuten boven drempel, in TT: het tempo van een proloog of korte tijdrit. Herstel even lang als de inspanning, rechtop.'),
('t_cp', 'pt', 'Potência crítica TT {n}×{d}', 'Objetivo fisiológico: Aumentar a potência crítica. Objetivo aero: Manter a posição TT a 108-115 % FTP em esforços de 3 a 4 minutos.', 'Esforços de 3 a 4 minutos acima do limiar, em TT: o ritmo de um prólogo ou de um contrarrelógio curto. Recuperação igual ao esforço, ereto.'),
('t_cp', 'ja', 'TTクリティカルパワー {n}×{d}', '生理学的目標：クリティカルパワーを高める。 エアロ目標：3〜4分の努力で108〜115 % FTPのTTポジションを保つ。', '閾値を超える3〜4分の努力をTTで：プロローグや短いTTのペース。回復は努力と同じ長さ、起き上がって。'),
('t_cp', 'tr', 'TT kritik güç {n}×{d}', 'Fizyolojik hedef: Kritik gücü yükseltmek. Aero hedefi: 3-4 dakikalık eforlarda %108-115 FTP''de TT pozisyonunu koru.', 'TT''de eşiğin üzerinde 3-4 dakikalık eforlar: prolog ya da kısa zamana karşı temposu. Eforla eşit toparlanma, dik.'),
('t_ou', 'fr', 'Sur-sous TT {n}×{d}', 'Objectif physiologique : Faire monter la puissance critique et la tolérance aux variations autour du seuil. Objectif aéro : Alterner 1'' à 108 % et 1'' à 95 % FTP sans quitter la position TT.', 'Les sur-sous font monter la puissance critique : chaque minute au-dessus du seuil est suivie d''une minute juste en dessous, sans vraie récupération, et tout se fait en TT. Pause redressée entre les séries.'),
('t_ou', 'en', 'TT over-unders {n}×{d}', 'Physiological goal: Raise critical power and tolerance to surges around threshold. Aero goal: Alternate 1'' at 108% and 1'' at 95% FTP without leaving the TT position.', 'Over-unders raise critical power: each minute above threshold is followed by a minute just below, with no real recovery, all in TT. Upright break between sets.'),
('t_ou', 'es', 'Sobre-bajo TT {n}×{d}', 'Objetivo fisiológico: Subir la potencia crítica y la tolerancia a los cambios alrededor del umbral. Objetivo aero: Alternar 1'' al 108 % y 1'' al 95 % FTP sin dejar la posición TT.', 'Los sobre-bajo suben la potencia crítica: cada minuto por encima del umbral va seguido de un minuto justo por debajo, sin recuperación real, todo en TT. Pausa erguido entre series.'),
('t_ou', 'it', 'Sopra-sotto TT {n}×{d}', 'Obiettivo fisiologico: Alzare la potenza critica e la tolleranza alle variazioni attorno alla soglia. Obiettivo aero: Alternare 1'' al 108 % e 1'' al 95 % FTP senza lasciare la posizione TT.', 'I sopra-sotto alzano la potenza critica: ogni minuto sopra soglia è seguito da un minuto appena sotto, senza vero recupero, tutto in TT. Pausa eretto tra le serie.'),
('t_ou', 'de', 'TT-Over-Under {n}×{d}', 'Physiologisches Ziel: Kritische Leistung und Toleranz für Wechsel um die Schwelle steigern. Aero-Ziel: 1'' bei 108 % und 1'' bei 95 % FTP abwechseln, ohne die TT-Position zu verlassen.', 'Over-Under steigern die kritische Leistung: Auf jede Minute über der Schwelle folgt eine Minute knapp darunter, ohne echte Erholung, alles in TT. Aufrechte Pause zwischen den Serien.'),
('t_ou', 'nl', 'TT-over-unders {n}×{d}', 'Fysiologisch doel: Kritisch vermogen en tolerantie voor wisselingen rond de drempel verhogen. Aerodoel: 1'' op 108 % en 1'' op 95 % FTP afwisselen zonder de TT-houding te verlaten.', 'Over-unders verhogen het kritisch vermogen: elke minuut boven drempel wordt gevolgd door een minuut net eronder, zonder echt herstel, alles in TT. Pauze rechtop tussen de series.'),
('t_ou', 'pt', 'Acima-abaixo TT {n}×{d}', 'Objetivo fisiológico: Aumentar a potência crítica e a tolerância às variações em torno do limiar. Objetivo aero: Alternar 1'' a 108 % e 1'' a 95 % FTP sem sair da posição TT.', 'Os acima-abaixo aumentam a potência crítica: cada minuto acima do limiar é seguido de um minuto logo abaixo, sem recuperação real, tudo em TT. Pausa ereto entre as séries.'),
('t_ou', 'ja', 'TTオーバーアンダー {n}×{d}', '生理学的目標：クリティカルパワーと閾値付近の変化への耐性を高める。 エアロ目標：TTポジションのまま108 %と95 % FTPを1分ずつ交互に。', 'オーバーアンダーはクリティカルパワーを高めます。閾値を超える1分の後に閾値直下の1分、実質的な回復はなく、全てTTで。セット間は起き上がって休憩。'),
('t_ou', 'tr', 'TT üst-alt {n}×{d}', 'Fizyolojik hedef: Kritik gücü ve eşik çevresindeki değişimlere toleransı yükseltmek. Aero hedefi: TT pozisyonundan çıkmadan 1'' %108 ve 1'' %95 FTP dönüşümlü.', 'Üst-alt çalışmaları kritik gücü artırır: eşiğin üstündeki her dakikayı gerçek toparlanma olmadan eşiğin hemen altında bir dakika izler, hepsi TT''de. Setler arasında dik mola.'),
('t_ss', 'fr', 'Sweet spot TT {n}×{d}', 'Objectif physiologique : Faire monter la FTP avec une fatigue mesurée. Objectif aéro : Tenir la position TT à 88-92 % FTP sur des blocs longs.', 'Le sweet spot développe la FTP avec une fatigue mesurée. En TT, c''est l''allure d''un CLM de 40 km à 1 h : la position doit tenir sous l''effort.'),
('t_ss', 'en', 'TT sweet spot {n}×{d}', 'Physiological goal: Raise your FTP with moderate fatigue. Aero goal: Hold the TT position at 88-92% FTP over long blocks.', 'Sweet spot builds FTP with moderate fatigue. In TT, it''s the pace of a 40 km TT or a 1 h effort: the position must hold under effort.'),
('t_ss', 'es', 'Sweet spot TT {n}×{d}', 'Objetivo fisiológico: Subir la FTP con una fatiga moderada. Objetivo aero: Mantener la posición TT al 88-92 % FTP en bloques largos.', 'El sweet spot desarrolla la FTP con una fatiga moderada. En TT es el ritmo de una CRI de 40 km o de 1 h: la posición debe aguantar con el esfuerzo.'),
('t_ss', 'it', 'Sweet spot TT {n}×{d}', 'Obiettivo fisiologico: Alzare la FTP con una fatica misurata. Obiettivo aero: Tenere la posizione TT all''88-92 % FTP su blocchi lunghi.', 'Lo sweet spot sviluppa la FTP con una fatica misurata. In TT è il ritmo di una crono di 40 km o di 1 h: la posizione deve tenere sotto sforzo.'),
('t_ss', 'de', 'TT-Sweet-Spot {n}×{d}', 'Physiologisches Ziel: Die FTP bei moderater Ermüdung steigern. Aero-Ziel: Die TT-Position bei 88-92 % FTP über lange Blöcke halten.', 'Sweet Spot entwickelt die FTP bei moderater Ermüdung. In TT ist es das Tempo eines 40-km-Zeitfahrens oder einer Stunde: Die Position muss unter Belastung halten.'),
('t_ss', 'nl', 'TT-sweetspot {n}×{d}', 'Fysiologisch doel: Je FTP verhogen met beperkte vermoeidheid. Aerodoel: De TT-houding vasthouden op 88-92 % FTP over lange blokken.', 'Sweet spot ontwikkelt de FTP met beperkte vermoeidheid. In TT is het het tempo van een tijdrit van 40 km of 1 uur: de houding moet standhouden onder inspanning.'),
('t_ss', 'pt', 'Sweet spot TT {n}×{d}', 'Objetivo fisiológico: Aumentar a FTP com fadiga moderada. Objetivo aero: Manter a posição TT a 88-92 % FTP em blocos longos.', 'O sweet spot desenvolve a FTP com fadiga moderada. Em TT, é o ritmo de um contrarrelógio de 40 km ou de 1 h: a posição tem de aguentar sob esforço.'),
('t_ss', 'ja', 'TTスイートスポット {n}×{d}', '生理学的目標：疲労を抑えてFTPを高める。 エアロ目標：長いブロックで88〜92 % FTPのTTポジションを保つ。', 'スイートスポットは疲労を抑えつつFTPを伸ばします。TTでは40 km TTや1時間の努力のペース：負荷の下でも姿勢を保つこと。'),
('t_ss', 'tr', 'TT sweet spot {n}×{d}', 'Fizyolojik hedef: Ölçülü yorgunlukla FTP''yi yükseltmek. Aero hedefi: Uzun bloklarda %88-92 FTP''de TT pozisyonunu koru.', 'Sweet spot, ölçülü yorgunlukla FTP''yi geliştirir. TT''de 40 km''lik zamana karşı ya da 1 saatlik efor temposudur: pozisyon efor altında dayanmalı.'),
('t_thr', 'fr', 'Seuil TT {n}×{d}', 'Objectif physiologique : Faire monter la FTP. Objectif aéro : Tenir la position TT au seuil (95-100 % FTP).', 'Blocs au seuil entièrement en TT : c''est là que la position coûte le plus, parce que la respiration et la fatigue poussent à se relever. Récupère redressé.'),
('t_thr', 'en', 'TT threshold {n}×{d}', 'Physiological goal: Raise your FTP. Aero goal: Hold the TT position at threshold (95-100% FTP).', 'Threshold blocks entirely in TT: this is where the position costs the most, because breathing and fatigue push you to sit up. Recover upright.'),
('t_thr', 'es', 'Umbral TT {n}×{d}', 'Objetivo fisiológico: Subir la FTP. Objetivo aero: Mantener la posición TT en el umbral (95-100 % FTP).', 'Bloques de umbral totalmente en TT: aquí es donde más cuesta la posición, porque la respiración y la fatiga empujan a incorporarse. Recupera erguido.'),
('t_thr', 'it', 'Soglia TT {n}×{d}', 'Obiettivo fisiologico: Alzare la FTP. Obiettivo aero: Tenere la posizione TT alla soglia (95-100 % FTP).', 'Blocchi alla soglia interamente in TT: è qui che la posizione costa di più, perché respiro e fatica spingono a rialzarsi. Recupera eretto.'),
('t_thr', 'de', 'TT-Schwelle {n}×{d}', 'Physiologisches Ziel: Die FTP steigern. Aero-Ziel: Die TT-Position an der Schwelle (95-100 % FTP) halten.', 'Schwellenblöcke komplett in TT: Hier kostet die Position am meisten, weil Atmung und Ermüdung zum Aufrichten drängen. Aufrecht erholen.'),
('t_thr', 'nl', 'TT-drempel {n}×{d}', 'Fysiologisch doel: Je FTP verhogen. Aerodoel: De TT-houding vasthouden op drempel (95-100 % FTP).', 'Drempelblokken volledig in TT: hier kost de houding het meest, omdat ademhaling en vermoeidheid je overeind duwen. Herstel rechtop.'),
('t_thr', 'pt', 'Limiar TT {n}×{d}', 'Objetivo fisiológico: Aumentar a FTP. Objetivo aero: Manter a posição TT no limiar (95-100 % FTP).', 'Blocos no limiar inteiramente em TT: é aqui que a posição mais custa, porque a respiração e a fadiga empurram para levantar. Recupere ereto.'),
('t_thr', 'ja', 'TT閾値 {n}×{d}', '生理学的目標：FTPを高める。 エアロ目標：閾値（95〜100 % FTP）でTTポジションを保つ。', '閾値ブロックを全てTTで：呼吸と疲労で起き上がりたくなるため、最も姿勢を保つのが難しい強度です。回復は起き上がって。'),
('t_thr', 'tr', 'TT eşik {n}×{d}', 'Fizyolojik hedef: FTP''yi yükseltmek. Aero hedefi: Eşikte (%95-100 FTP) TT pozisyonunu koru.', 'Tamamen TT''de eşik blokları: nefes ve yorgunluk doğrulmaya ittiği için pozisyonun en çok zorladığı yer burası. Dik toparlan.'),
('v_44', 'fr', 'PMA {n}×{d} + TT', 'Objectif physiologique : Développer la PMA (VO2max). Objectif aéro : Rester en position TT pendant chaque récupération de PMA et sur le bloc final à 70 % FTP, souffle court compris.', 'Intervalles longs de PMA (format 4×4'' de Helgerud) en position libre ; chaque récupération et le bloc final à 70 % FTP se font en TT, pour apprendre à rester bas quand le souffle est court.'),
('v_44', 'en', 'VO2max {n}×{d} + TT', 'Physiological goal: Build your VO2max. Aero goal: Stay in the TT position during every VO2max recovery and the final block at 70% FTP, even when out of breath.', 'Long VO2max intervals (Helgerud''s 4×4'' format) in any position; every recovery and the final block at 70% FTP are in TT, to learn to stay low when you''re out of breath.'),
('v_44', 'es', 'VO2max {n}×{d} + TT', 'Objetivo fisiológico: Desarrollar el VO2max. Objetivo aero: Mantener la posición TT en cada recuperación de VO2max y en el bloque final al 70 % FTP, aun sin aliento.', 'Intervalos largos de VO2max (formato 4×4'' de Helgerud) en posición libre; cada recuperación y el bloque final al 70 % FTP se hacen en TT, para aprender a seguir abajo sin aliento.'),
('v_44', 'it', 'VO2max {n}×{d} + TT', 'Obiettivo fisiologico: Sviluppare il VO2max. Obiettivo aero: Restare in posizione TT in ogni recupero di VO2max e nel blocco finale al 70 % FTP, anche col fiato corto.', 'Intervalli lunghi di VO2max (formato 4×4'' di Helgerud) in posizione libera; ogni recupero e il blocco finale al 70 % FTP si fanno in TT, per imparare a restare bassi col fiato corto.'),
('v_44', 'de', 'VO2max {n}×{d} + TT', 'Physiologisches Ziel: Die VO2max entwickeln. Aero-Ziel: In jeder VO2max-Erholung und im Schlussblock bei 70 % FTP in TT-Position bleiben, auch wenn die Luft knapp ist.', 'Lange VO2max-Intervalle (4×4''-Format nach Helgerud) in freier Position; jede Erholung und der Schlussblock bei 70 % FTP in TT, um tief zu bleiben, wenn die Luft knapp ist.'),
('v_44', 'nl', 'VO2max {n}×{d} + TT', 'Fysiologisch doel: Je VO2max ontwikkelen. Aerodoel: In TT-houding blijven tijdens elk VO2max-herstel en het slotblok op 70 % FTP, ook als je adem tekortkomt.', 'Lange VO2max-intervallen (4×4''-formaat van Helgerud) in vrije houding; elk herstel en het slotblok op 70 % FTP in TT, om laag te leren blijven als je adem tekortkomt.'),
('v_44', 'pt', 'VO2max {n}×{d} + TT', 'Objetivo fisiológico: Desenvolver o VO2max. Objetivo aero: Ficar na posição TT em cada recuperação de VO2max e no bloco final a 70 % FTP, mesmo sem fôlego.', 'Intervalos longos de VO2max (formato 4×4'' de Helgerud) em posição livre; cada recuperação e o bloco final a 70 % FTP são em TT, para aprender a ficar baixo sem fôlego.'),
('v_44', 'ja', 'VO2max {n}×{d} + TT', '生理学的目標：VO2maxを伸ばす。 エアロ目標：息が苦しくても、VO2maxの回復と最後の70 % FTPブロックではTTポジションを保つ。', 'ロングVO2maxインターバル（Helgerudの4×4''形式）をポジション自由で。回復と最後の70 % FTPブロックはTTで、息が苦しいときも低く保つ練習。'),
('v_44', 'tr', 'VO2max {n}×{d} + TT', 'Fizyolojik hedef: VO2max''ı geliştirmek. Aero hedefi: Nefesin kesik olsa da her VO2max toparlanmasında ve %70 FTP''deki son blokta TT pozisyonunda kal.', 'Serbest pozisyonda uzun VO2max intervalleri (Helgerud 4×4'' formatı); her toparlanma ve %70 FTP''deki son blok TT''de, nefes kesikken alçakta kalmayı öğrenmek için.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
), ind(lang, many, one) AS (VALUES ('fr', 'Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Réussite : 1 passage en TT validé (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).'), ('en', 'Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Success: 1 TT block validated (≥ 95% of the block in TT, no exit of 20 s or more).'), ('es', 'Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Éxito: 1 tramo en TT validado (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).'), ('it', 'Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Riuscita: 1 tratto in TT validato (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).'), ('de', 'Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Erfolg: 1 TT-Abschnitt bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).'), ('nl', 'Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Geslaagd: 1 TT-stuk gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).'), ('pt', 'Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Sucesso: 1 trecho em TT validado (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).'), ('ja', '達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '達成条件：TTブロック1本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。'), ('tr', 'Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Başarı: 1 TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).')
), s(skey, typ, week, n, d, minutes, k, aero, blocks, lc) AS (VALUES

