), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"clm_short_8w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "clm_short_8w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "clm_short_8w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "clm_short_8w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'clm_short_8w_name', 'clm_short_8w_description', 'clm_short_8w_objective', 8, 'advanced', 'training', 4, true, '{"name": {"fr": "CLM court et triathlon S en aéro", "en": "Short TT and sprint triathlon in aero", "es": "CRI corta y triatlón sprint en aero", "it": "Crono corta e triathlon sprint in aero", "de": "Kurzes Zeitfahren und Sprinttriathlon in Aero", "nl": "Korte tijdrit en sprinttriatlon in aero", "pt": "Contrarrelógio curto e triatlo sprint em aero", "ja": "短いTTとスプリント・トライアスロン（エアロ）", "tr": "Aero''da kısa zamana karşı ve sprint triatlon"}, "objective": {"fr": "Tenir la position TT à l''allure d''un CLM de 10 à 20 km, jusqu''à 25 minutes d''affilée à 100 % FTP.", "en": "Hold the TT position at 10 to 20 km TT pace, up to 25 minutes in a row at 100% FTP.", "es": "Mantener la posición TT al ritmo de una CRI de 10 a 20 km, hasta 25 minutos seguidos al 100 % FTP.", "it": "Tenere la posizione TT al ritmo di una crono da 10 a 20 km, fino a 25 minuti di fila al 100 % FTP.", "de": "Die TT-Position im Tempo eines 10- bis 20-km-Zeitfahrens halten, bis zu 25 Minuten am Stück bei 100 % FTP.", "nl": "De TT-houding vasthouden op het tempo van een tijdrit van 10 tot 20 km, tot 25 minuten aan één stuk op 100 % FTP.", "pt": "Manter a posição TT no ritmo de um contrarrelógio de 10 a 20 km, até 25 minutos seguidos a 100 % FTP.", "ja": "10〜20 kmのTTペースでポジションを保つ。100 % FTPで最大25分連続。", "tr": "10-20 km''lik zamana karşı temposunda TT pozisyonunu koru, %100 FTP''de aralıksız 25 dakikaya kadar."}, "description": {"fr": "8 semaines pour un CLM de 10 à 20 km ou le vélo d''un triathlon S. Seuil, PMA et puissance critique, une simulation d''allure CLM par semaine (de 3×6'' à 25'' d''affilée) et une sortie d''endurance TT. Semaine 8 : affûtage avant la course.", "en": "8 weeks for a 10 to 20 km TT or the bike leg of a sprint triathlon. Threshold, VO2max and critical power, one TT race-pace simulation a week (from 3×6'' to 25'' in a row) and one TT endurance ride. Week 8: taper before the race.", "es": "8 semanas para una CRI de 10 a 20 km o la bici de un triatlón sprint. Umbral, VO2max y potencia crítica, una simulación de ritmo de CRI por semana (de 3×6'' a 25'' seguidos) y una salida de resistencia TT. Semana 8: puesta a punto antes de la carrera.", "it": "8 settimane per una crono da 10 a 20 km o la frazione bici di un triathlon sprint. Soglia, VO2max e potenza critica, una simulazione a ritmo crono a settimana (da 3×6'' a 25'' di fila) e un''uscita di resistenza TT. Settimana 8: scarico prima della gara.", "de": "8 Wochen für ein 10- bis 20-km-Zeitfahren oder die Radstrecke eines Sprinttriathlons. Schwelle, VO2max und kritische Leistung, eine Renntempo-Simulation pro Woche (von 3×6'' bis 25'' am Stück) und eine TT-Ausdauerfahrt. Woche 8: Tapering vor dem Rennen.", "nl": "8 weken voor een tijdrit van 10 tot 20 km of het fietsdeel van een sprinttriatlon. Drempel, VO2max en kritisch vermogen, één simulatie op tijdrittempo per week (van 3×6'' tot 25'' aan één stuk) en één TT-duurrit. Week 8: taperen voor de wedstrijd.", "pt": "8 semanas para um contrarrelógio de 10 a 20 km ou a bike de um triatlo sprint. Limiar, VO2max e potência crítica, uma simulação de ritmo de contrarrelógio por semana (de 3×6'' a 25'' seguidos) e um treino de resistência TT. Semana 8: polimento antes da prova.", "ja": "10〜20 kmのTTやスプリント・トライアスロンのバイクのための8週間。閾値、VO2max、クリティカルパワー、週1回のTTレースペース・シミュレーション（3×6''から25''連続まで）とTT持久ライド。8週目はレース前の調整。", "tr": "10-20 km''lik zamana karşı ya da sprint triatlonun bisiklet etabı için 8 hafta. Eşik, VO2max ve kritik güç, haftada bir zamana karşı temposu simülasyonu (3×6''''den aralıksız 25''''ye) ve bir TT dayanıklılık sürüşü. 8. hafta: yarış öncesi toparlanma."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'clm_short_8w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'clm_short_8w_w1s1_name'), (1, 2, 'clm_short_8w_w1s2_name'), (1, 3, 'clm_short_8w_w1s3_name'), (1, 4, 'clm_short_8w_w1s4_name'), (2, 1, 'clm_short_8w_w2s1_name'), (2, 2, 'clm_short_8w_w2s2_name'), (2, 3, 'clm_short_8w_w2s3_name'), (2, 4, 'clm_short_8w_w2s4_name'), (3, 1, 'clm_short_8w_w3s1_name'), (3, 2, 'clm_short_8w_w3s2_name'), (3, 3, 'clm_short_8w_w3s3_name'), (3, 4, 'clm_short_8w_w3s4_name'), (4, 1, 'clm_short_8w_w4s1_name'), (4, 2, 'clm_short_8w_w4s2_name'), (4, 3, 'clm_short_8w_w4s3_name'), (5, 1, 'clm_short_8w_w5s1_name'), (5, 2, 'clm_short_8w_w5s2_name'), (5, 3, 'clm_short_8w_w5s3_name'), (5, 4, 'clm_short_8w_w5s4_name'), (6, 1, 'clm_short_8w_w6s1_name'), (6, 2, 'clm_short_8w_w6s2_name'), (6, 3, 'clm_short_8w_w6s3_name'), (6, 4, 'clm_short_8w_w6s4_name'), (7, 1, 'clm_short_8w_w7s1_name'), (7, 2, 'clm_short_8w_w7s2_name'), (7, 3, 'clm_short_8w_w7s3_name'), (7, 4, 'clm_short_8w_w7s4_name'), (8, 1, 'clm_short_8w_w8s1_name'), (8, 2, 'clm_short_8w_w8s2_name'), (8, 3, 'clm_short_8w_w8s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'clm_short_8w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
